{
  "name": "@amykit/plugin-command",
  "version": "0.6.0",
  "description": "Any command line tool, reached by a name the config allows.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/command"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import { CommandOutcome, CommandRunner, Commands } from "@amykit/core";

export interface AllowedCommandsConfig {
  /** Name to command line. The only place a command line is ever written. */
  allow: Readonly<Record<string, string>>;
  cwd?: string;
  timeoutMs?: number;
}

/**
 * The command line tools a workflow is allowed to reach, by name.
 *
 * One adapter rather than one per tool. `pup` for the monitors, `ntn` for the
 * pages, whatever next year's is: the machine learns none of them, it learns
 * that a name in the config maps to a line somebody wrote down.
 */
export class AllowedCommands implements Commands {
  constructor(
    private readonly runner: CommandRunner,
    private readonly config: AllowedCommandsConfig,
  ) {}

  available(): readonly string[] {
    return Object.keys(this.config.allow).sort();
  }

  async run(
    name: string,
    args: readonly string[] = [],
    options: { cwd?: string } = {},
  ): Promise<CommandOutcome> {
    const at = new Date().toISOString();
    const line = this.config.allow[name];

    // Refused by name, with what there was. A workflow asking for something
    // nobody allowed is a config that has not caught up with it, and that is
    // a sentence somebody can act on rather than a silent no-op.
    if (!line) {
      const known = this.available();
      return {
        name,
        ok: false,
        exitCode: -1,
        at,
        output:
          `\`${name}\` is not a command this install allows. ` +
          `Allowed: ${known.length > 0 ? known.join(", ") : "nothing"}`,
      };
    }

    // The arguments become positional parameters rather than being spliced
    // into the line. `sh -c 'pup monitors "$@"' sh --since 1h` passes them
    // through untouched, so an argument carrying a quote, a semicolon or a
    // backtick is an argument and never a second command.
    const result = await this.runner.run("sh", ["-c", `${line} "$@"`, "sh", ...args], {
      cwd: options.cwd ?? this.config.cwd ?? undefined,
      timeoutMs: this.config.timeoutMs,
    });

    return {
      name,
      ok: result.ok,
      exitCode: result.exitCode,
      at,
      output: `${result.stdout}${result.stderr}`.trim(),
    };
  }
}

import { ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  allow: {
    type: "record",
    required: true,
    description:
      "the commands a workflow may run, by name. The name is what a workflow asks for; the value is the command line it stands for, and this is the only place one is written",
  },
  cwd: {
    type: "string",
    description: "where a command runs when it does not say, defaulting to the state directory",
    default: "",
  },
  timeoutMs: {
    type: "number",
    description: "how long one command may run before it is given up on",
    default: 5 * 60 * 1000,
  },
} satisfies ConfigSchema;

export { AllowedCommands } from "./AllowedCommands.js";
export type { AllowedCommandsConfig } from "./AllowedCommands.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";

import { definePlugin } from "@amykit/core";
import { AllowedCommands } from "./AllowedCommands.js";
import { configSchema } from "./config.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-command",
  configSchema,
  register(registry, ctx) {
    // The action and the port together, which is what the registry asks of a
    // plugin adding an action the core does not ship. `run-command` is not in
    // the core catalogue because nothing has yet shown it is general — a
    // second workflow needing it is what would move it there.
    registry.action(
      "run-command",
      { port: "commands", method: "run" },
      new AllowedCommands(ctx.runner, {
        allow: (ctx.config.allow ?? {}) as Record<string, string>,
        cwd: (ctx.config.cwd) || ctx.paths.state,
        timeoutMs: ctx.config.timeoutMs,
      }),
    );
  },
});
